import{_ as s,o as a,c as r,ag as e}from"./chunks/framework.D1ek-kcM.js";const v=JSON.parse('{"title":"Single Database","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/single-database.md","filePath":"getting-started/single-database.md","lastUpdated":1788526021000}'),i={name:"getting-started/single-database.md"},n={viewBox:"0 0 688 372",role:"img","aria-label":"Single shared database for all tenants",style:{width:"100%",height:"auto","font-family":"var(--vp-font-family-base)"}};function o(l,t,d,h,c,x){return a(),r("div",null,[t[1]||(t[1]=e('<h1 id="single-database" tabindex="-1">Single Database <a class="header-anchor" href="#single-database" aria-label="Permalink to &quot;Single Database&quot;">​</a></h1><p>In the <strong>single database</strong> variant of the SaaS module, every tenant on the platform shares <strong>one database</strong>. All merchants&#39; records sit in the same tables and are separated by a tenant identifier, so each merchant only ever sees their own store data.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How tenant data is separated inside one shared database</li><li>When this variant is the right choice</li><li>What it means for setup, backups, and upgrades</li></ul></div><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2>',4)),(a(),r("svg",n,[...t[0]||(t[0]=[e('<title>Single shared database for all tenants</title><defs><marker id="arrow-single" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" style="fill:var(--vp-c-text-3);"></path></marker></defs><rect x="16" y="16" width="152" height="48" rx="8" style="fill:var(--vp-c-bg-soft);stroke:var(--vp-c-divider);stroke-width:1;"></rect><text x="92" y="45" text-anchor="middle" style="fill:var(--vp-c-text-1);font-size:12px;font-weight:600;">Super admin panel</text><rect x="184" y="16" width="152" height="48" rx="8" style="fill:var(--vp-c-bg-soft);stroke:var(--vp-c-divider);stroke-width:1;"></rect><text x="260" y="45" text-anchor="middle" style="fill:var(--vp-c-text-1);font-size:12px;font-weight:600;">Tenant A store</text><rect x="352" y="16" width="152" height="48" rx="8" style="fill:var(--vp-c-bg-soft);stroke:var(--vp-c-divider);stroke-width:1;"></rect><text x="428" y="45" text-anchor="middle" style="fill:var(--vp-c-text-1);font-size:12px;font-weight:600;">Tenant B store</text><rect x="520" y="16" width="152" height="48" rx="8" style="fill:var(--vp-c-bg-soft);stroke:var(--vp-c-divider);stroke-width:1;"></rect><text x="596" y="45" text-anchor="middle" style="fill:var(--vp-c-text-1);font-size:12px;font-weight:600;">Tenant C store</text><line x1="92" y1="64" x2="92" y2="100" style="stroke:var(--vp-c-text-3);stroke-width:1.2;" marker-end="url(#arrow-single)"></line><line x1="260" y1="64" x2="260" y2="100" style="stroke:var(--vp-c-text-3);stroke-width:1.2;" marker-end="url(#arrow-single)"></line><line x1="428" y1="64" x2="428" y2="100" style="stroke:var(--vp-c-text-3);stroke-width:1.2;" marker-end="url(#arrow-single)"></line><line x1="596" y1="64" x2="596" y2="100" style="stroke:var(--vp-c-text-3);stroke-width:1.2;" marker-end="url(#arrow-single)"></line><rect x="16" y="104" width="656" height="56" rx="8" style="fill:var(--vp-c-brand-soft);stroke:var(--vp-c-brand-1);stroke-width:1;"></rect><text x="344" y="128" text-anchor="middle" style="fill:var(--vp-c-text-1);font-size:13px;font-weight:600;">Bagisto SaaS platform</text><text x="344" y="147" text-anchor="middle" style="fill:var(--vp-c-text-2);font-size:11px;">detects the tenant from the domain and filters every query by tenant</text><line x1="344" y1="160" x2="344" y2="194" style="stroke:var(--vp-c-text-3);stroke-width:1.2;" marker-end="url(#arrow-single)"></line><path d="M 16 214 L 16 344 A 328.0 16 0 0 0 672 344 L 672 214" style="fill:var(--vp-c-bg-soft);stroke:var(--vp-c-brand-1);stroke-width:1.5;"></path><ellipse cx="344.0" cy="214" rx="328.0" ry="16" style="fill:var(--vp-c-bg-soft);stroke:var(--vp-c-brand-1);stroke-width:1.5;"></ellipse><text x="344" y="248" text-anchor="middle" style="fill:var(--vp-c-text-1);font-size:13px;font-weight:600;">One shared database</text><rect x="26" y="266" width="132" height="26" rx="13" style="fill:var(--vp-c-brand-soft);stroke:none;"></rect><text x="92" y="283" text-anchor="middle" style="fill:var(--vp-c-text-2);font-size:11px;">Platform data</text><rect x="194" y="266" width="132" height="26" rx="13" style="fill:var(--vp-c-brand-soft);stroke:none;"></rect><text x="260" y="283" text-anchor="middle" style="fill:var(--vp-c-text-2);font-size:11px;">Tenant A rows</text><rect x="362" y="266" width="132" height="26" rx="13" style="fill:var(--vp-c-brand-soft);stroke:none;"></rect><text x="428" y="283" text-anchor="middle" style="fill:var(--vp-c-text-2);font-size:11px;">Tenant B rows</text><rect x="530" y="266" width="132" height="26" rx="13" style="fill:var(--vp-c-brand-soft);stroke:none;"></rect><text x="596" y="283" text-anchor="middle" style="fill:var(--vp-c-text-2);font-size:11px;">Tenant C rows</text><text x="344" y="320" text-anchor="middle" style="fill:var(--vp-c-text-2);font-size:11px;">same tables — every row carries its tenant id</text>',30)])])),t[2]||(t[2]=e('<ul><li>The platform runs on a single database connection for every tenant.</li><li>Each record — products, categories, orders, customers — carries the tenant it belongs to.</li><li>When a merchant opens their storefront or admin panel, the platform detects the tenant from the domain and automatically limits every query to that tenant&#39;s data.</li><li>A new merchant is provisioned instantly: no new database is created, only their tenant record and store data.</li></ul><h2 id="advantages" tabindex="-1">Advantages <a class="header-anchor" href="#advantages" aria-label="Permalink to &quot;Advantages&quot;">​</a></h2><ul><li><strong>Simple to set up and maintain</strong> — one database to configure, migrate, back up, and monitor.</li><li><strong>Lower infrastructure cost</strong> — a single database server can host a large number of stores.</li><li><strong>One-step upgrades</strong> — migrations and module updates run once for the whole platform.</li><li><strong>Fast onboarding</strong> — tenants are ready to sell as soon as they register.</li><li><strong>Platform-wide reporting</strong> — the super admin&#39;s cross-tenant views (customers, products, orders) read from one place. See <a href="/super-admin/tenant-data">Tenant Data</a>.</li></ul><h2 id="things-to-keep-in-mind" tabindex="-1">Things to keep in mind <a class="header-anchor" href="#things-to-keep-in-mind" aria-label="Permalink to &quot;Things to keep in mind&quot;">​</a></h2><ul><li>All tenants share the same database resources, so a very large store can affect others.</li><li>Backing up or exporting a single tenant means extracting that tenant&#39;s rows rather than copying a whole database.</li><li>Tenants cannot be moved onto their own database server individually.</li></ul><div class="tip custom-block"><p class="custom-block-title">Best for</p><p>A high volume of small and medium stores, where low cost and simple maintenance matter more than physical data separation. If tenants need strictly separated data or their own backups, use <a href="/getting-started/multi-database">Multiple Databases</a> instead.</p></div>',6))])}const f=s(i,[["render",o]]);export{v as __pageData,f as default};
